using System.Globalization;
using Microsoft.CodeAnalysis;
namespace XamlG.Compiler;

internal static class PrimitiveValueParser
{
    public static bool TryParse(string text, SpecialType type, out object? value)
    {
        value = null;
        if (type is SpecialType.System_String or SpecialType.System_Object) { value = text; return true; }
        if (type == SpecialType.System_Char) { if (text.Length != 1) return false; value = text[0]; return true; }
        var clrType = type switch
        {
            SpecialType.System_Boolean => typeof(bool), SpecialType.System_Byte => typeof(byte), SpecialType.System_SByte => typeof(sbyte),
            SpecialType.System_Int16 => typeof(short), SpecialType.System_UInt16 => typeof(ushort), SpecialType.System_Int32 => typeof(int),
            SpecialType.System_UInt32 => typeof(uint), SpecialType.System_Int64 => typeof(long), SpecialType.System_UInt64 => typeof(ulong),
            SpecialType.System_Single => typeof(float), SpecialType.System_Double => typeof(double), SpecialType.System_Decimal => typeof(decimal), _ => null
        };
        if (clrType == null) return false;
        if (type == SpecialType.System_Boolean && (text == "0" || text == "1")) { value = text == "1"; return true; }
        if (type is SpecialType.System_Single or SpecialType.System_Double)
        {
            if (text == "INF") { value = type == SpecialType.System_Single ? (object)float.PositiveInfinity : double.PositiveInfinity; return true; }
            if (text == "-INF") { value = type == SpecialType.System_Single ? (object)float.NegativeInfinity : double.NegativeInfinity; return true; }
        }
        try { value = Convert.ChangeType(text, clrType, CultureInfo.InvariantCulture); return true; }
        catch (FormatException) { return false; }
        catch (OverflowException) { return false; }
    }
}

using System.Collections.Immutable;
using Microsoft.CodeAnalysis;
using XamlG.Roslyn;
using XamlG.Syntax;
namespace XamlG.Compiler;

/// <summary>Resolves conversions to typed operations. Only framework-independent primitive parsing runs at compile time.</summary>
public sealed class ValueBinder
{
    private readonly BindingContext _context;
    private readonly MarkupBinder _markup;
    public ValueBinder(BindingContext context) { _context = context; _markup = new(context); }
    public BoundExpression? BindText(string text, ITypeSymbol target, NamespaceScope scope, TextSpan span, ISymbol? member = null)
    {
        _context.Cancellation.ThrowIfCancellationRequested();
        if (text.StartsWith("{}", StringComparison.Ordinal)) text = text.Substring(2);
        else if (text.StartsWith("{", StringComparison.Ordinal))
        {
            var syntax = MarkupExtensionParser.Parse(text, span, _context.Diagnostics.Add);
            var value = syntax == null ? null : _markup.Bind(syntax, target, scope);
            return value == null ? null : Coerce(value, target, span);
        }
        var converted = TryText(text, target, scope, span, member);
        if (converted == null) _context.Report("XG1008", $"Cannot convert '{text}' to '{target.ToDisplayString()}'.", span);
        return converted;
    }
    public BoundExpression? TryText(string text, ITypeSymbol target, NamespaceScope scope, TextSpan span, ISymbol? member = null)
    {
        foreach (var rule in _context.Profile.TextConversionRules)
            if (rule.TryConvert(_context, text, target, scope, span, member, out var result)) return result;
        if (target is INamedTypeSymbol nullable && nullable.OriginalDefinition.SpecialType == SpecialType.System_Nullable_T)
        { var inner = TryText(text, nullable.TypeArguments[0], scope, span, member); return inner == null ? null : new BoundCastExpression(inner, target, span); }
        if (PrimitiveValueParser.TryParse(text, target.SpecialType, out var primitive))
            return new BoundConstantExpression(primitive, target.SpecialType == SpecialType.System_Object ? _context.Types.Special(SpecialType.System_String) : target, span);
        if (target.TypeKind == TypeKind.Enum && target is INamedTypeSymbol enumeration)
        {
            var fields = ImmutableArray.CreateBuilder<IFieldSymbol>();
            foreach (var name in text.Split(','))
            {
                var field = enumeration.GetMembers().OfType<IFieldSymbol>().FirstOrDefault(f => f.HasConstantValue && string.Equals(f.Name, name.Trim(), StringComparison.OrdinalIgnoreCase));
                if (field == null)
                {
                    if (fields.Count == 0 && enumeration.EnumUnderlyingType != null && PrimitiveValueParser.TryParse(text, enumeration.EnumUnderlyingType.SpecialType, out var number))
                        return new BoundCastExpression(new BoundConstantExpression(number, enumeration.EnumUnderlyingType, span), target, span);
                    return null;
                }
                fields.Add(field);
            }
            return fields.Count == 0 ? null : new BoundEnumExpression(fields.ToImmutable(), target, span);
        }
        if (target.HasMetadataName(ClrNames.Type))
        {
            var referenced = ResolveTypeLiteral(text, scope, span, report: false);
            return referenced == null ? null : new BoundTypeExpression(referenced, target, span);
        }
        var converter = FindConverter(member) ?? FindConverter(target);
        if (converter != null) return new BoundConverterExpression(text, converter, target, span);
        var parse = target.Members(ClrNames.Parse).OfType<IMethodSymbol>()
            .Where(m => m.IsStatic && !m.IsGenericMethod && _context.Types.IsAccessible(m) && m.Parameters.Length is 1 or 2 &&
                m.Parameters[0].Type.SpecialType == SpecialType.System_String && (m.Parameters.Length == 1 || m.Parameters[1].Type.HasMetadataName(ClrNames.IFormatProvider) || m.Parameters[1].Type.HasMetadataName(ClrNames.CultureInfo)) &&
                _context.Types.Compilation.ClassifyCommonConversion(m.ReturnType, target).IsImplicit)
            .OrderByDescending(m => m.Parameters.Length).FirstOrDefault();
        if (parse != null) return new BoundParseExpression(text, parse, target, span);
        if (target.HasMetadataName(ClrNames.Uri) && target is INamedTypeSymbol uri)
        {
            var constructor = uri.InstanceConstructors.FirstOrDefault(c => c.Parameters.Length == 2 && c.Parameters[0].Type.SpecialType == SpecialType.System_String && c.Parameters[1].Type.TypeKind == TypeKind.Enum);
            var relative = constructor?.Parameters[1].Type.GetMembers("RelativeOrAbsolute").OfType<IFieldSymbol>().FirstOrDefault();
            if (constructor != null && relative != null) return new BoundNewExpression(constructor, ImmutableArray.Create<BoundExpression>(new BoundConstantExpression(text, _context.Types.Special(SpecialType.System_String), span), new BoundStaticExpression(relative, relative.Type, span)), span);
        }
        return null;
    }
    private INamedTypeSymbol? FindConverter(ISymbol? symbol)
    {
        if (symbol == null) return null;
        foreach (var attribute in symbol.GetAttributes())
        {
            if (attribute.AttributeClass == null || !_context.Types.Configuration.TypeConverterAttributes.Contains(attribute.AttributeClass.MetadataName())) continue;
            var value = attribute.ConstructorArguments.FirstOrDefault().Value;
            var type = value as INamedTypeSymbol ?? (value is string name ? _context.Types.Find(name.Split(',')[0].Trim()) : null);
            if (type == null || !_context.Types.IsAccessible(type) || !type.InstanceConstructors.Any(c => c.Parameters.Length == 0 && _context.Types.IsAccessible(c))) continue;
            for (var current = type; current != null; current = current.BaseType) if (current.HasMetadataName(ClrNames.TypeConverter)) return type;
        }
        return null;
    }
    public ITypeSymbol? ResolveTypeLiteral(string name, NamespaceScope scope, TextSpan span, string? typeArguments = null, bool report = true)
    {
        if (name.EndsWith("[]", StringComparison.Ordinal))
        {
            var element = ResolveTypeLiteral(name.Substring(0, name.Length - 2), scope, span, typeArguments, report);
            return element == null ? null : _context.Types.Compilation.CreateArrayTypeSymbol(element);
        }
        return _context.ResolveType(name, scope, span, typeArguments, report);
    }
    public BoundExpression? BindNode(XamlSyntaxNode syntax, ITypeSymbol target, NamespaceScope scope, int nameScope = 0, bool normalizeText = true)
    {
        _context.Cancellation.ThrowIfCancellationRequested();
        if (syntax is XamlTextSyntax text) return BindText(normalizeText ? XmlWhitespace.Normalize(text.Value, scope.PreserveSpace) : text.Value, target, scope, syntax.Span);
        if (syntax is not XamlElementSyntax element) return null;
        var nested = scope.Push(element); var name = nested.Expand(element.Name);
        if (name.Namespace != null && XamlNames.IsLanguage(name.Namespace))
        {
            if (name.LocalName == "Null") return Coerce(new BoundConstantExpression(null, null, syntax.Span), target, syntax.Span);
            if (name.LocalName == "Array")
            {
                var typeText = element.Attributes.FirstOrDefault(a => a.Name == "Type")?.Value;
                ITypeSymbol? itemType = null;
                if (typeText != null)
                {
                    var typeValue = BindText(typeText, _context.Types.Find(ClrNames.Type)!, nested, element.NameSpan);
                    itemType = (typeValue as BoundTypeExpression)?.ReferencedType;
                }
                itemType ??= (target as IArrayTypeSymbol)?.ElementType;
                if (itemType == null) { _context.Report("XG1021", "x:Array requires an element Type.", syntax.Span); return null; }
                var values = ImmutableArray.CreateBuilder<BoundExpression>();
                foreach (var child in element.Children.Where(c => c is XamlElementSyntax || c is XamlTextSyntax t && !string.IsNullOrWhiteSpace(t.Value)))
                { var value = BindNode(child, itemType, nested, nameScope); if (value != null) values.Add(value); }
                return Coerce(new BoundArrayExpression(values.ToImmutable(), _context.Types.Compilation.CreateArrayTypeSymbol(itemType), syntax.Span), target, syntax.Span);
            }
            if (name.LocalName is "Type" or "Static" or "Reference" or "True" or "False")
            {
                var args = element.Attributes.Where(a => !a.IsNamespace).Select(a => new MarkupArgumentSyntax(a.Name, a.Value, a.Span)).ToImmutableArray();
                var value = _markup.Bind(new(element.Name, args, element.Span), target, nested); return value == null ? null : Coerce(value, target, syntax.Span);
            }
        }
        var type = _context.ResolveType(element.Name, nested, element.NameSpan, nested.Directive(element, "TypeArguments")?.Value);
        if (type == null) return null;
        if (!element.Children.OfType<XamlElementSyntax>().Any())
        {
            var content = string.Concat(element.Children.OfType<XamlTextSyntax>().Select(t => t.Value));
            if (type.SpecialType != SpecialType.None || type.TypeKind == TypeKind.Enum || type.IsValueType || type.HasMetadataName(ClrNames.Uri))
            {
                var value = TryText(type.SpecialType == SpecialType.System_String ? content : XmlWhitespace.Normalize(content, nested.PreserveSpace), type, nested, element.Span);
                if (value != null) return Coerce(value, target, syntax.Span);
            }
        }
        var bound = _context.Objects.Bind(element, scope, type, false, nameScope);
        if (bound == null) return null;
        var provided = _markup.Provide(bound, target, syntax.Span);
        return Coerce(provided ?? new BoundObjectExpression(bound), target, syntax.Span);
    }
    public ITypeSymbol? PeekNodeType(XamlSyntaxNode syntax, NamespaceScope scope)
    {
        if (syntax is XamlTextSyntax) return _context.Types.Special(SpecialType.System_String);
        if (syntax is not XamlElementSyntax element) return null;
        var nested = scope.Push(element); var name = nested.Expand(element.Name);
        if (name.Namespace != null && XamlNames.IsLanguage(name.Namespace) && name.LocalName == "Null") return null;
        return _context.ResolveType(element.Name, nested, element.NameSpan, nested.Directive(element, "TypeArguments")?.Value, report: false);
    }
    public bool TryGetStringLiteral(XamlSyntaxNode syntax, NamespaceScope scope, out string value)
    {
        if (syntax is XamlTextSyntax text) { value = text.Value; return true; }
        if (syntax is XamlElementSyntax element && PeekNodeType(element, scope)?.SpecialType == SpecialType.System_String)
        { value = string.Concat(element.Children.OfType<XamlTextSyntax>().Select(t => t.Value)); return true; }
        value = string.Empty; return false;
    }
    public BoundExpression? Coerce(BoundExpression value, ITypeSymbol target, TextSpan span)
    {
        if (value.Type == null)
        {
            if (target.AcceptsNull()) return new BoundConstantExpression(null, target, span);
            _context.Report("XG1022", $"Null cannot be assigned to '{target}'.", span); return null;
        }
        var conversion = _context.Types.Compilation.ClassifyConversion(value.Type, target);
        if (conversion.IsImplicit) return value;
        if (conversion.Exists && value.Type.SpecialType == SpecialType.System_Object) return new BoundCastExpression(value, target, span);
        if (value is BoundConstantExpression { Value: string text } && TryText(text, target, NamespaceScope.Empty, span) is { } converted) return converted;
        _context.Report("XG1023", $"Value of type '{value.Type}' cannot be assigned to '{target}'.", span); return null;
    }
}

using System.Collections.Immutable;
using System.Threading;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using XamlG.Roslyn;
using XamlG.Syntax;
namespace XamlG.Compiler;

/// <summary>The reusable compilation entry point. It has no dependency on generator, workspace, MSBuild or browser APIs.</summary>
public sealed class XamlCompiler
{
    public BoundDocument Bind(XamlSyntaxTree syntax, CSharpCompilation compilation, XamlFrameworkProfile? profile = null, XamlCompilerOptions? options = null, CancellationToken cancellationToken = default)
    {
        profile ??= XamlFrameworkProfile.Portable;
        return Bind(syntax, new RoslynTypeSystem(compilation, profile.TypeSystem), profile, options, cancellationToken);
    }
    public BoundDocument Bind(XamlSyntaxTree syntax, RoslynTypeSystem types, XamlFrameworkProfile profile, XamlCompilerOptions? options = null, CancellationToken cancellationToken = default)
    {
        options ??= new(); var context = new BindingContext(syntax, types, profile, options, cancellationToken);
        var root = syntax.Root; BoundObject? bound = null; string? className = null; var modifier = "public";
        if (root != null)
        {
            var scope = NamespaceScope.Empty.Push(root); var directive = scope.Directive(root, "Class"); className = directive?.Value;
            var classModifier = scope.Directive(root, "ClassModifier");
            if (classModifier != null)
            { if (classModifier.Value is "public" or "internal") modifier = classModifier.Value; else context.Report("XG1018", "x:ClassModifier must be public or internal.", classModifier.ValueSpan); }
            if (className != null)
            {
                context.RootClass = types.Find(className);
                if (context.RootClass == null) context.Report("XG1030", $"Code-behind class '{className}' was not found in the Roslyn compilation.", directive!.ValueSpan);
                else
                {
                    foreach (var reference in context.RootClass.DeclaringSyntaxReferences)
                        if (reference.GetSyntax(cancellationToken) is TypeDeclarationSyntax declaration && !declaration.Modifiers.Any(SyntaxKind.PartialKeyword))
                            context.Report("XG1030", $"Code-behind class '{className}' must be partial.", directive!.ValueSpan);
                }
            }
            var declared = context.ResolveType(root.Name, scope, root.NameSpan, scope.Directive(root, "TypeArguments")?.Value);
            if (declared != null)
            {
                if (context.RootClass != null && !types.Compilation.ClassifyCommonConversion(context.RootClass, declared).IsImplicit)
                    context.Report("XG1030", $"Code-behind '{className}' does not derive from '{declared}'.", root.NameSpan);
                else bound = context.Objects.Bind(root, NamespaceScope.Empty, context.RootClass ?? declared, true);
            }
        }
        MetadataDiagnosticCollector.Collect(context);
        var document = new BoundDocument(syntax, bound, className, context.RootClass, modifier, context.Diagnostics.ToImmutableArray(), context.Symbols.ToImmutableArray(), profile, options) { Runtime = context.Runtime };
        foreach (var pass in profile.Passes) { cancellationToken.ThrowIfCancellationRequested(); document = pass.Run(document, context); }
        return document;
    }
}

using XamlG.Syntax;
using Xunit;
namespace XamlG.Tests;

public sealed class SyntaxTests
{
    [Theory]
    [InlineData("<Root/>")]
    [InlineData("<?xml version='1.0'?>\r\n<!--hello--><Root A='&amp;' >a<![CDATA[<b>]]>c</Root>")]
    [InlineData("<Root><Child /></Root>")]
    public void RoundTripsEverySourceCharacter(string source)
    { var syntax = XamlSyntaxTree.Parse(source); Assert.False(syntax.HasErrors, string.Join(";", syntax.Diagnostics)); Assert.Equal(source, syntax.ToString()); }
    [Fact]
    public void PreservesAttributeQuotesAndTrivia()
    {
        const string source = "<!--keep--><Root  Text = 'old' Other=\"yes\" />"; var tree = XamlSyntaxTree.Parse(source);
        var change = XamlSyntaxEditor.SetAttribute(tree, tree.Root!, "Text", "a'b&c");
        var edited = tree.WithChanges(new[] { change }, tree.Version);
        Assert.Equal("<!--keep--><Root  Text = 'a&apos;b&amp;c' Other=\"yes\" />", edited.Text);
        Assert.Equal("a'b&c", edited.Root!.Attributes[0].Value); Assert.Equal(1, edited.Version);
    }
    [Fact]
    public void RenameChangesBothTagsOnly()
    {
        var tree = XamlSyntaxTree.Parse("<Old Text='Old'><!--Old--></Old>");
        var result = tree.WithChanges(XamlSyntaxEditor.RenameElement(tree, tree.Root!, "New"), 0);
        Assert.Equal("<New Text='Old'><!--Old--></New>", result.Text);
    }
    [Fact]
    public void RejectsStaleAndOverlappingEdits()
    {
        var tree = XamlSyntaxTree.Parse("<Root/>");
        Assert.Throws<InvalidOperationException>(() => tree.WithChanges(Array.Empty<XamlTextChange>(), 1));
        Assert.Throws<ArgumentException>(() => tree.WithChanges(new[] { new XamlTextChange(new(1, 3), "A"), new XamlTextChange(new(2, 1), "B") }, 0));
    }
    [Fact]
    public void NamespaceShadowingIsPersistent()
    {
        var tree = XamlSyntaxTree.Parse("<a:Root xmlns:a='one'><a:Child xmlns:a='two'/></a:Root>");
        var rootScope = NamespaceScope.Empty.Push(tree.Root!); var childScope = rootScope.Push((XamlElementSyntax)tree.Root!.Children[0]);
        Assert.Equal("one", rootScope.Expand("a:T").Namespace); Assert.Equal("two", childScope.Expand("a:T").Namespace);
    }
    [Theory]
    [InlineData("<Root><Child></Root>")]
    [InlineData("<Root A='unfinished")]
    [InlineData("<Root/><Second/>")]
    [InlineData("<Root A='1' A='2'/>")]
    [InlineData("<!DOCTYPE Root [<!ENTITY x SYSTEM 'file:///etc/passwd'>]><Root>&x;</Root>")]
    public void ReportsMalformedInputWithoutThrowing(string source) => Assert.True(XamlSyntaxTree.Parse(source).HasErrors);
    [Fact]
    public void RecoveryDoesNotConsumeParentsClosingTag()
    {
        var tree = XamlSyntaxTree.Parse("<Root><Child></Root>"); Assert.True(tree.HasErrors);
        Assert.Equal("</Root>", tree.Text.Substring(tree.Root!.CloseTagSpan.Start, tree.Root.CloseTagSpan.Length));
    }
    [Fact]
    public void HonorsCancellationAndLimits()
    {
        using var cancellation = new CancellationTokenSource(); cancellation.Cancel();
        Assert.Throws<OperationCanceledException>(() => XamlSyntaxTree.Parse("<Root/>", cancellationToken: cancellation.Token));
        Assert.True(XamlSyntaxTree.Parse(new string('<', 100), options: new(MaximumCharacters: 10)).HasErrors);
        Assert.True(XamlSyntaxTree.Parse("<A><B><C><D/></C></B></A>", options: new(MaximumDepth: 1)).HasErrors);
    }
    [Fact]
    public void MarkupArgumentsRespectNestedBracesAndQuotes()
    {
        const string text = "{Outer {Inner Value='a,b'}, Name='x=y', More={Other A=1, B=2}}"; var diagnostics = new List<XamlDiagnostic>();
        var syntax = MarkupExtensionParser.Parse(text, new(0, text.Length), diagnostics.Add)!;
        Assert.Empty(diagnostics); Assert.Equal(3, syntax.Arguments.Length); Assert.Null(syntax.Arguments[0].Name); Assert.Equal("x=y", syntax.Arguments[1].Value);
    }
    [Fact]
    public void ParsesNestedGenericAndNullableTypes()
    {
        var errors = new List<XamlDiagnostic>(); var type = XamlTypeNameParser.Parse("g:Map(x:String, g:List(x:Int32?))", new(0, 33), errors.Add);
        Assert.Empty(errors); Assert.Equal(2, type!.Arguments.Length); Assert.True(type.Arguments[1].Arguments[0].Nullable);
    }
    [Fact]
    public void LineMapUsesUtf16AndRecognizesCrLf()
    { var map = new SourceLineMap("a\r\nb\nc"); Assert.Equal(new SourceLinePosition(1, 0), map.GetPosition(3)); Assert.Equal(5, map.GetOffset(new(2, 0))); }
}

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
namespace XamlG.Tests;
internal static class CompilationFactory
{
    private static readonly MetadataReference[] References = ((string)AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES")!).Split(Path.PathSeparator).Select(p => MetadataReference.CreateFromFile(p)).ToArray();
    public static CSharpCompilation Create(string source) => CSharpCompilation.Create("TestAssembly", new[] { CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.Preview)) }, References, new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
}

using System.Collections.Immutable;
using Microsoft.CodeAnalysis;
using XamlG.Compiler;
using XamlG.Roslyn;
using XamlG.Syntax;
using Xunit;
namespace XamlG.Tests;

public sealed class BindingTests
{
    internal const string Model = """
        using System; using System.Collections.Generic;
        namespace Demo {
          [AttributeUsage(AttributeTargets.Property)] public class ContentAttribute : Attribute {}
          public class View { [Content] public List<Item> Children {get;} = new(); public string Title {get;set;} = string.Empty; public int Count {get;set;} public object Value {get;set;} public Type Type {get;set;} }
          public class Item { public string Text {get;set;} public string Name {get;set;} public int Value {get;set;} }
          public static class Layout { public static void SetRow(Item item, int row) {} public static int GetRow(Item item) => 0; }
          public class EchoExtension { public EchoExtension(string value) { Value=value; } public string Value {get;set;} public string ProvideValue(IServiceProvider services) => Value; }
          public class Generic<T> { public T Value {get;set;} }
          public partial class Main : View { }
        }
        """;
    internal static XamlFrameworkProfile Profile => XamlFrameworkProfile.Portable with { TypeSystem = new XamlTypeSystemConfiguration { ContentAttributes = ImmutableArray.Create("Demo.ContentAttribute"), NamespaceMappings = ImmutableArray.Create(new XmlNamespaceMapping("urn:demo", "Demo", "TestAssembly")) } };
    private static BoundDocument Bind(string body) => new XamlCompiler().Bind(XamlSyntaxTree.Parse(body), CompilationFactory.Create(Model), Profile);
    [Fact]
    public void ResolvesTypedChildrenAttachedPropertiesAndMarkupExtensions()
    {
        var result = Bind("<View xmlns='urn:demo' Title='{Echo hello}' Count='42'><Item Text='one' Layout.Row='2'/><Item Text='two'/></View>");
        Assert.True(result.Success, string.Join(";", result.Diagnostics)); Assert.Equal(4, result.Root!.Assignments.Length);
        Assert.Contains(result.Symbols, s => s.Symbol is IMethodSymbol m && m.Name == "SetRow");
    }
    [Theory]
    [InlineData("Count='not-an-int'", "XG1008")]
    [InlineData("Unknown='x'", "XG1005")]
    [InlineData("Count='{x:Null}'", "XG1022")]
    public void InvalidSemanticsHaveSourceDiagnostics(string attribute, string code)
    { var result = Bind("<View xmlns='urn:demo' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' " + attribute + "/>"); Assert.False(result.Success); Assert.Contains(result.Diagnostics, d => d.Code == code); }
    [Fact]
    public void GenericTypesUseRoslynConstruction()
    {
        var result = Bind("<Generic xmlns='urn:demo' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' x:TypeArguments='x:Int32' Value='21'/>");
        Assert.True(result.Success, string.Join(";", result.Diagnostics)); Assert.Equal(SpecialType.System_Int32, result.Root!.Type.TypeArguments[0].SpecialType);
    }
    [Fact]
    public void CodeBehindUsesExistingCompilationIdentity()
    {
        var result = Bind("<View xmlns='urn:demo' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' x:Class='Demo.Main'/>");
        Assert.True(result.Success, string.Join(";", result.Diagnostics)); Assert.Equal("Demo.Main", result.ClassSymbol!.ToDisplayString());
    }
    [Fact]
    public void RejectsDuplicateScalarAssignments()
    { var result = Bind("<View xmlns='urn:demo' Title='one'><View.Title>two</View.Title></View>"); Assert.Contains(result.Diagnostics, d => d.Code == "XG1014"); }
    [Fact]
    public void TypeResolutionUsesAssemblyAndArity()
    {
        var types = new RoslynTypeSystem(CompilationFactory.Create(Model), Profile.TypeSystem);
        Assert.NotNull(types.Resolve("clr-namespace:Demo;assembly=TestAssembly", "View").Type);
        Assert.Null(types.Resolve("clr-namespace:Demo;assembly=Missing", "View").Type);
        Assert.Null(types.Resolve("urn:demo", "Generic").Type); Assert.NotNull(types.Resolve("urn:demo", "Generic", 1).Type);
    }
}
